INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_BRADING_MEXICAN_PHOENIX','secondary scholarship','D. A. Brading, Mexican Phoenix: Our Lady of Guadalupe — Image and Tradition across Five Centuries (Cambridge University Press, 2001)','The cult of Our Lady of Guadalupe at Tepeyac and the documented Tonantzin association (esp. Sahagun''s report); used for the Guadalupe-Tonantzin syncretism seam.'),
 ('SRC_PIEPER_FOLK_SAINTS_GUATEMALA','secondary scholarship','Jim Pieper, Guatemala''s Folk Saints: Maximon/San Simon, Rey Pascual, Judas, Lucifer, and Others (Pieper and Associates, 2002)','The living Guatemalan folk-saint cult of Maximon and his identification with San Simon and Judas Iscariot, and the underlying Maya figure Mam; used for the Mam/Maximon syncretism seam.')
ON CONFLICT (source_id) DO NOTHING;

CREATE TEMP TABLE _e(id text,name text,etype text,cat text,trad text,dom text,conf text,note text) ON COMMIT DROP;
INSERT INTO _e VALUES
 ('ENT_PCB_MESOAMERICAN_RELIGION','Pre-Columbian Mesoamerican Religion','Collective','Pantheon','Mesoamerican','pantheon/tradition hub','B','Hub collective for the pre-Columbian (Nahua and Maya) deities included only at documented Catholic syncretism seams. Pre-Columbian source; not a full pantheon roster. Practice: the indigenous religions of central Mexico and the Maya highlands, suppressed and partly continued in syncretic Catholic devotion after 1521.'),
 ('ENT_PCB_TONANTZIN','Tonantzin','Goddess','God','Mesoamerican','mother, earth, fertility','B','Nahuatl ''Our Revered Mother'', a Nahua mother-earth title/goddess with a shrine at Tepeyac near Mexico City. Attestation: Bernardino de Sahagun (16th c.) records that indigenous pilgrims called the Guadalupan shrine at Tepeyac ''Tonantzin''. Pre-Columbian source. The Tonantzin-Guadalupe association is the canonical documented Mesoamerican-Catholic syncretism seam (Brading).'),
 ('ENT_PCB_MAM','Mam','God','God','Mesoamerican','earth, ancestors, mountains','C','Maya ''Grandfather''/ancestral earth figure of the Guatemalan highlands publicly regarded as the indigenous antecedent of the living folk saint Maximon (San Simon). Pre-Columbian source; only publicly attested function modeled, no ritual interiors. In highland Maya Catholic practice the derived folk saint Maximon is publicly identified with San Simon and with Judas Iscariot (Pieper); that identification attaches to the received folk-saint figure rather than to Mam directly.');

INSERT INTO entities (entity_id,canonical_name,tradition,entity_type,category,primary_domains,cult_scope,evidence_confidence,review_status,inclusion_basis,earth_association_score,chthonic_flag,serpent_flag,short_note)
