 ('ENT_PCB_TONANTZIN','SRC_BRADING_MEXICAN_PHOENIX','scholarly attestation','attestation'),
 ('ENT_PCB_MAM','SRC_PIEPER_FOLK_SAINTS_GUATEMALA','scholarly attestation','attestation');

INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
SELECT s.id,s.src,s.etype,s.note FROM _s s
