CREATE TEMP TABLE _p(id text,per text,note text) ON COMMIT DROP;
INSERT INTO _p VALUES
 ('ENT_PCB_MESOAMERICAN_RELIGION','PER_PCB_POSTCLASSIC_MESOAMERICA','Hub collective for the pre-Columbian (Nahua and Maya) deities included only at documented Catholic syncretism seams. Pre-Columbian source; not a full pantheon roster. Practice: the indigenous religions of central Mexico and the Maya highlands, suppressed and partly continued in syncretic Catholic devotion after 1521.'),
 ('ENT_PCB_TONANTZIN','PER_PCB_POSTCLASSIC_MESOAMERICA','Nahuatl ''Our Revered Mother'', a Nahua mother-earth title/goddess with a shrine at Tepeyac near Mexico City. Attestation: Bernardino de Sahagun (16th c.) records that indigenous pilgrims called the Guadalupan shrine at Tepeyac ''Tonantzin''. Pre-Columbian source. The Tonantzin-Guadalupe association is the canonical documented Mesoamerican-Catholic syncretism seam (Brading).'),
 ('ENT_PCB_MAM','PER_PCB_POSTCLASSIC_MESOAMERICA','Maya ''Grandfather''/ancestral earth figure of the Guatemalan highlands publicly regarded as the indigenous antecedent of the living folk saint Maximon (San Simon). Pre-Columbian source; only publicly attested function modeled, no ritual interiors. In highland Maya Catholic practice the derived folk saint Maximon is publicly identified with San Simon and with Judas Iscariot (Pieper); that identification attaches to the received folk-saint figure rather than to Mam directly.');

INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
SELECT p.id,p.per,'high',p.note,(SELECT es.source_id FROM entity_sources es WHERE es.entity_id=p.id ORDER BY es.source_id LIMIT 1),'reviewed'
FROM _p p
WHERE EXISTS(SELECT 1 FROM entities e WHERE e.entity_id=p.id) AND EXISTS(SELECT 1 FROM periods x WHERE x.period_id=p.per)
ON CONFLICT DO NOTHING;

CREATE TEMP TABLE _r(s text,t text,o text,c text,ra text) ON COMMIT DROP;
INSERT INTO _r VALUES
 ('ENT_PCB_TONANTZIN','member_of','ENT_PCB_MESOAMERICAN_RELIGION','high','Tonantzin is a Nahua deity within the pre-Columbian Mesoamerican religious complex represented by the hub collective.'),
 ('ENT_PCB_MAM','member_of','ENT_PCB_MESOAMERICAN_RELIGION','high','Mam is a Maya ancestral/earth figure within the pre-Columbian Mesoamerican religious complex represented by the hub collective.'),
 ('ENT_EMC_OUR_LADY_GUADALUPE','syncretized_with','ENT_PCB_TONANTZIN','high','Our Lady of Guadalupe is the textbook case of Catholic-Mesoamerican syncretism, her Tepeyac shrine identified by indigenous devotees with the Nahua mother-earth goddess Tonantzin; Sahagun records pilgrims calling the site Tonantzin (Brading, Mexican Phoenix).');

